# (typ, siatka EN, PL, LA, region, opis)
N = 'nerv'
NERV = [
 (N,'Roots of brachial plexus','Korzenie splotu ramiennego','Radices plexus brachialis','bark','Gałęzie brzuszne nn. rdzeniowych C5–Th1; wychodzą między mm. pochyłymi przednim i środkowym i łączą się w trzy pnie.'),
 (N,'Superior trunk of brachial plexus','Pień górny splotu ramiennego','Truncus superior','bark','Powstaje z C5–C6 (punkt Erba); stąd odchodzi n. nadłopatkowy. Uszkodzenie → porażenie Erba–Duchenne\'a (ramię przywiedzione, obrócone do wewnątrz).'),
 (N,'Middle trunk of brachial plexus','Pień środkowy splotu ramiennego','Truncus medius','bark','Kontynuacja korzenia C7.'),
 (N,'Inferior trunk of brachial plexus','Pień dolny splotu ramiennego','Truncus inferior','bark','Powstaje z C8–Th1; leży na I żebrze za tętnicą podobojczykową. Uszkodzenie → porażenie Klumpke (dłoń „szponiasta”).'),
 (N,'Anterior division of superior trunk of brachial plexus','Część przednia pnia górnego','Divisio anterior trunci superioris','bark','Wchodzi w skład pęczka bocznego.'),
 (N,'Anterior division of middle trunk of brachial plexus','Część przednia pnia środkowego','Divisio anterior trunci medii','bark','Wchodzi w skład pęczka bocznego.'),
 (N,'Anterior division of inferior trunk of brachial plexus','Część przednia pnia dolnego','Divisio anterior trunci inferioris','bark','Tworzy pęczek przyśrodkowy.'),
 (N,'Posterior division of superior trunk of brachial plexus','Część tylna pnia górnego','Divisio posterior trunci superioris','bark','Wchodzi w skład pęczka tylnego.'),
 (N,'Posterior division of middle trunk of brachial plexus','Część tylna pnia środkowego','Divisio posterior trunci medii','bark','Wchodzi w skład pęczka tylnego.'),
 (N,'Posterior division of inferior trunk of brachial plexus','Część tylna pnia dolnego','Divisio posterior trunci inferioris','bark','Wchodzi w skład pęczka tylnego.'),
 (N,'Posterior cord of brachial plexus','Pęczek tylny splotu ramiennego','Fasciculus posterior','bark','Z części tylnych trzech pni (C5–Th1). Daje nn. pachowy, promieniowy, podłopatkowy dolny i piersiowo-grzbietowy.'),
 (N,'Dorsal scapular nerve','Nerw grzbietowy łopatki','Nervus dorsalis scapulae','bark','C4–C5. Zaopatruje mm. równoległoboczne i dźwigacz łopatki.'),
 (N,'Long thoracic nerve','Nerw piersiowy długi','Nervus thoracicus longus','bark','C5–C7. Zaopatruje m. zębaty przedni; uszkodzenie → „łopatka skrzydłowata”.'),
 (N,'Subclavian nerve','Nerw podobojczykowy','Nervus subclavius','bark','C5–C6. Zaopatruje m. podobojczykowy.'),
 (N,'Suprascapular nerve','Nerw nadłopatkowy','Nervus suprascapularis','bark','C5–C6. Przechodzi przez wcięcie łopatki pod więzadłem poprzecznym górnym; zaopatruje mm. nadgrzebieniowy i podgrzebieniowy oraz staw ramienny.'),
 (N,'Lateral pectoral nerve','Nerw piersiowy boczny','Nervus pectoralis lateralis','bark','C5–C7 (z pęczka bocznego). Zaopatruje głównie m. piersiowy większy.'),
 (N,'Medial pectoral nerve','Nerw piersiowy przyśrodkowy','Nervus pectoralis medialis','bark','C8–Th1 (z pęczka przyśrodkowego). Zaopatruje mm. piersiowe mniejszy i większy.'),
 (N,'Thoracodorsal nerve','Nerw piersiowo-grzbietowy','Nervus thoracodorsalis','bark','C6–C8 (z pęczka tylnego). Zaopatruje m. najszerszy grzbietu.'),
 (N,'Inferior subscapular nerve','Nerw podłopatkowy dolny','Nervus subscapularis inferior','bark','C5–C6. Zaopatruje m. obły większy i dolną część m. podłopatkowego.'),
 (N,'Axillary nerve','Nerw pachowy','Nervus axillaris','bark','C5–C6. Przez otwór czworoboczny okrąża szyjkę chirurgiczną kości ramiennej; zaopatruje mm. naramienny i obły mniejszy. Zagrożony przy złamaniach szyjki chirurgicznej i zwichnięciu stawu ramiennego.'),
 (N,'Muscular branches of axillary nerve','Gałęzie mięśniowe n. pachowego','Rami musculares n. axillaris','bark','Unerwiają m. naramienny i m. obły mniejszy.'),
 (N,'Superior lateral brachial cutaneous nerve','Nerw skórny boczny górny ramienia','Nervus cutaneus brachii lateralis superior','ramie','Gałąź n. pachowego; czucie skóry nad m. naramiennym (okolica „naszywki wojskowej”).'),
 (N,'Musculocutaneous nerve','Nerw mięśniowo-skórny','Nervus musculocutaneus','ramie','C5–C7 (pęczek boczny). Przebija m. kruczo-ramienny; zaopatruje mm. kruczo-ramienny, dwugłowy ramienia i ramienny, a kończy się jako n. skórny boczny przedramienia.'),
 (N,'Lateral antebrachial cutaneous nerve','Nerw skórny boczny przedramienia','Nervus cutaneus antebrachii lateralis','przedramie','Zakończenie n. mięśniowo-skórnego; czucie skóry promieniowej strony przedramienia.'),
 (N,'Medial brachial cutaneous nerve','Nerw skórny przyśrodkowy ramienia','Nervus cutaneus brachii medialis','ramie','Th1–Th2 (z pęczka przyśrodkowego); czucie skóry przyśrodkowej strony ramienia.'),
 (N,'Medial antebrachial cutaneous nerve','Nerw skórny przyśrodkowy przedramienia','Nervus cutaneus antebrachii medialis','przedramie','C8–Th1 (pęczek przyśrodkowy); czucie skóry łokciowej strony przedramienia.'),
 (N,'Anterior branch of medial antebrachial cutaneous nerve','Gałąź przednia n. skórnego przyśrodkowego przedramienia','Ramus anterior','przedramie','Skóra przedniej i przyśrodkowej powierzchni przedramienia.'),
 (N,'Posterior branch of medial antebrachial cutaneous nerve','Gałąź tylna n. skórnego przyśrodkowego przedramienia','Ramus posterior','przedramie','Skóra tylno-przyśrodkowej powierzchni przedramienia.'),
 (N,'Median nerve','Nerw pośrodkowy','Nervus medianus','ramie','C5–Th1; powstaje z pęczka bocznego i przyśrodkowego. Biegnie z tętnicą ramienną, przechodzi między głowami m. nawrotnego obłego i przez kanał nadgarstka. Zaopatruje zginacze przedramienia (bez FCU i części FDP), mięśnie kłębu kciuka i mm. glistowate I–II. Ucisk w kanale nadgarstka = zespół cieśni nadgarstka.'),
 (N,'Muscular branches of median nerve','Gałęzie mięśniowe n. pośrodkowego','Rami musculares n. mediani','przedramie','Unerwiają m. nawrotny obły, zginacz promieniowy nadgarstka, dłoniowy długi i zginacz powierzchowny palców.'),
 (N,'Anterior interosseous nerve of forearm','Nerw międzykostny przedni przedramienia','Nervus interosseus antebrachii anterior','przedramie','Gałąź n. pośrodkowego na błonie międzykostnej; unerwia m. zginacz długi kciuka, część promieniową m. zginacza głębokiego palców i m. nawrotny czworoboczny. Uszkodzenie → brak „kółka OK”.'),
 (N,'Palmar branch of median nerve','Gałąź dłoniowa n. pośrodkowego','Ramus palmaris n. mediani','dlon','Odchodzi nad kanałem nadgarstka; czucie skóry nasady kciuka i środka dłoni.'),
 (N,'Common palmar digital branches of median nerve','Nerwy dłoniowe palców wspólne (n. pośrodkowy)','Nervi digitales palmares communes','dlon','Trzy gałęzie rozdzielające się na nerwy własne palców I–IV; unerwiają też mm. glistowate I–II.'),
 (N,'Proper palmar digital branches of median nerve','Nerwy dłoniowe palców własne (n. pośrodkowy)','Nervi digitales palmares proprii','dlon','Czucie dłoniowej powierzchni kciuka, palców II, III i promieniowej połowy IV oraz grzbietowej strony paliczków dalszych.'),
 (N,'(Communicating branch of median nerve with ulnar nerve)','Gałąź łącząca n. pośrodkowego z n. łokciowym','Ramus communicans cum n. ulnari','dlon','Połączenie w dłoni między nerwami dłoniowymi wspólnymi (częsty wariant).'),
 (N,'Ulnar nerve','Nerw łokciowy','Nervus ulnaris','ramie','C8–Th1 (pęczek przyśrodkowy). Biegnie w bruździe n. łokciowego za nadkłykciem przyśrodkowym („kość łokciowa”), dalej między głowami m. zginacza łokciowego nadgarstka i przez kanał Guyona. Zaopatruje FCU, część FDP (IV–V) i większość mięśni krótkich ręki. Uszkodzenie → „ręka szponiasta”.'),
 (N,'Muscular branches of ulnar nerve','Gałęzie mięśniowe n. łokciowego','Rami musculares n. ulnaris','przedramie','Unerwiają m. zginacz łokciowy nadgarstka i łokciową część m. zginacza głębokiego palców.'),
 (N,'Palmar branch of ulnar nerve','Gałąź dłoniowa n. łokciowego','Ramus palmaris n. ulnaris','dlon','Czucie skóry dłoniowej w okolicy kłębu palca małego.'),
 (N,'Dorsal branch of ulnar nerve','Gałąź grzbietowa n. łokciowego','Ramus dorsalis n. ulnaris','dlon','Odchodzi w dolnej części przedramienia; czucie łokciowej części grzbietu ręki.'),
 (N,'Dorsal digital branches of ulnar nerve','Nerwy grzbietowe palców (n. łokciowy)','Nervi digitales dorsales','dlon','Czucie grzbietowej powierzchni palca V, IV i łokciowej strony III (do stawu międzypaliczkowego dalszego).'),
 (N,'Superficial branch of ulnar nerve','Gałąź powierzchowna n. łokciowego','Ramus superficialis n. ulnaris','dlon','Czuciowa (oraz unerwia m. dłoniowy krótki); dzieli się na nerwy dłoniowe palców.'),
 (N,'Common palmar digital branches of ulnar nerve','Nerwy dłoniowe palców wspólne (n. łokciowy)','Nervi digitales palmares communes','dlon','Rozdzielają się na nerwy własne palców V i IV.'),
 (N,'Proper palmar digital branches of ulnar nerve','Nerwy dłoniowe palców własne (n. łokciowy)','Nervi digitales palmares proprii','dlon','Czucie dłoniowej powierzchni palca V i łokciowej połowy palca IV.'),
 (N,'Deep branch of ulnar nerve','Gałąź głęboka n. łokciowego','Ramus profundus n. ulnaris','dlon','Okrąża hak kości haczykowatej; unerwia mięśnie kłębu palca małego, mm. międzykostne, glistowate III–IV, przywodziciel kciuka i głęboką głowę zginacza krótkiego kciuka.'),
 (N,'Radial nerve','Nerw promieniowy','Nervus radialis','ramie','C5–Th1 (pęczek tylny). Biegnie w bruździe n. promieniowego kości ramiennej. Zaopatruje m. trójgłowy, łokciowy, ramienno-promieniowy i prostowniki; uszkodzenie → „opadająca ręka” (porażenie prostowników nadgarstka).'),
 (N,'Muscular branches of radial nerve','Gałęzie mięśniowe n. promieniowego','Rami musculares n. radialis','ramie','Unerwiają głowy m. trójgłowego ramienia, m. łokciowy, ramienny (część boczna) i ramienno-promieniowy.'),
 (N,'Inferior lateral brachial cutaneous nerve','Nerw skórny boczny dolny ramienia','Nervus cutaneus brachii lateralis inferior','ramie','Czucie skóry bocznej strony ramienia (dolna część).'),
 (N,'Posterior antebrachial cutaneous nerve','Nerw skórny tylny przedramienia','Nervus cutaneus antebrachii posterior','przedramie','Czucie skóry tylnej powierzchni przedramienia.'),
 (N,'Deep branch of radial nerve','Gałąź głęboka n. promieniowego','Ramus profundus n. radialis','przedramie','Przechodzi przez m. odwracacz (arkada Frohsego); unerwia prostowniki i odwracacz; jako n. międzykostny tylny biegnie na błonie międzykostnej.'),
 (N,'Posterior interosseous nerve of forearm','Nerw międzykostny tylny przedramienia','Nervus interosseus antebrachii posterior','przedramie','Zakończenie gałęzi głębokiej; unerwia prostowniki palców, kciuka i nadgarstka (czuciowo — torebkę stawu).'),
 (N,'Superficial branch of radial nerve','Gałąź powierzchowna n. promieniowego','Ramus superficialis n. radialis','przedramie','Czuciowa; biegnie pod m. ramienno-promieniowym i wychodzi na grzbiet ręki.'),
 (N,'Dorsal digital branches of radial nerve','Nerwy grzbietowe palców (n. promieniowy)','Nervi digitales dorsales','dlon','Czucie grzbietowej powierzchni kciuka, palca II, III i promieniowej połowy IV (do stawu międzypaliczkowego bliższego).'),
]
